import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.deal(caller, 1 ether);

        // First call: lock in a guess, should succeed in reference
        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(keccak256("first"));

        // Record the block number after first call
        // Note: guesses mapping is private, but we can infer block number via revert behavior
        // The second call will either succeed (changing block) or revert (keeping block unchanged)
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        bool reverted = false;
        try c.lockInGuess{value: 1 ether}(keccak256("second")) {
            // succeeded - but what block number does the caller have?
            // We cannot read it directly, but we can settle to check
            // Actually, we rely on the property: second call should succeed only in buggy version
            // In reference, it reverts because block != 0; in mutant, it proceeds
            // But we need a public observable difference.
            // Simplest: The second call reverts in reference, succeeds in mutant.
            reverted = false;
        } catch {
            reverted = true;
        }
        // The reference reverts on second call; the mutant does not.
        assertTrue(reverted);
    }
}

