pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash) public {
        vm.deal(address(this), 1 ether);
        c.lockInGuess{value: 1 ether}(hash);
        uint balanceBefore = address(c).balance;
        // Ensure balance is exactly 2 ether for the condition to matter
        vm.assume(balanceBefore == 2 ether);
        // We need to skip to a block where settle can be called
        vm.roll(block.number + 2);
        // Now check that settle reduces balance by 2 ether if it succeeds
        // We can't know if the guess is correct, but we can observe the balance change
        uint balAfter = address(c).balance;
        // The mutant only transfers 0 ether, so balance stays same; reference transfers 2 ether
        // The general rule: if balance was 2 ether, after settle it must be either 0 or 2 (unchanged if revert or wrong guess)
        // But the mutant always leaves balance unchanged (0 transfer) while reference reduces to 0 on correct guess
        // To distinguish, we assert that if settle succeeds, balance must not stay 2 ether (i.e., it must change)
        // Actually, we can catch revert: if it reverts, balance unchanged; if it doesn't, balance must decrease
        // Simpler: after settle, balanceBefore - address(c).balance must be either 0 (no transfer) or 2 ether (transfer)
        bool couldBeMutant = (balanceBefore - address(c).balance) == 0 ether;
        bool couldBeRef = (balanceBefore - address(c).balance) == 2 ether;
        // The reference ensures that if transfer happens, it's 2 ether; mutant never transfers 2.
        // So the invariant: the difference is either 0 or 2, but not 0 always.
        // Actually, we want a rule that holds for reference but fails for mutant.
        // For reference: if settle doesn't revert, diff is either 0 (wrong guess) or 2 (correct guess).
        // For mutant: if settle doesn't revert, diff is always 0.
        // So the rule: after calling settle, diff ∈ {0, 2}. This is true for both, so not good.
        // Better: After lockInGuess and with balance exactly 2, there exists a future call to settle that changes balance by 2 ether.
        // But that's existential, not universal.
        // Let's try: The sum of transfers to msg.sender over a full settle cycle cannot be 0 when guess matches.
        // Hard.
        // Alternative: Use a known correct guess by mining a block with known hash.
        // Let's bound hash to be the correct answer for a specific future block.
    }
}

